# frozen_string_literal: true

require "json"

module Mail2rss26
  # The feed list: which addresses exist, and what each one is a feed of.
  #
  # This is *configuration*, not state (the plan's line, and the reason there is
  # no panel and no sign-up flow). It is generated by the NixOS module from
  # `builtins.toJSON` in Phase 6, which is the whole reason the format is JSON —
  # Nix writes it in one builtin and Ruby reads it out of stdlib, so neither
  # side gains a dependency. The schema is documented in the README; this file
  # is its only implementation and the errors below are the spec's teeth.
  #
  # Everything here is validated even though it comes from our own module.
  # A feed name becomes a directory name and an address decides which feed a
  # stranger's mail lands in, so "the generator would never do that" is not a
  # thing worth being wrong about once.
  class Config
    # Anything wrong with the file itself. The CLI turns this into a deferral
    # (75): an operator has to fix the file, and the queue is what holds the
    # newsletters that arrived while it was broken.
    class Error < StandardError; end

    # Bumped only if the shape changes incompatibly, so an old module and a new
    # binary fail on the first delivery with a clear message rather than
    # half-understanding each other.
    SCHEMA_VERSION = 1

    DEFAULT_PATH = "/etc/mail2rss26/feeds.json"

    # For development and for the test suite: it puts the config path somewhere
    # the OpenSMTPD `mda` line does not have to mention, which is convenient
    # exactly once — when there is no OpenSMTPD.
    PATH_ENV = "MAIL2RSS26_CONFIG"

    # One configured feed. Deliberately five separate fields, because three of
    # them are the three tokens of the plan's central decision and they have
    # three different lifecycles:
    #
    #   addresses  the incoming address(es) — public, ends up with whoever
    #              bought the newsletter's list,
    #   url        the feed's URL — secret, rotatable the day it leaks,
    #   id         the Atom <id> — permanent, and never changes, because
    #              changing it makes every reader show a year of archive as
    #              unread.
    #
    # None of them is derived from another, which is why the config states all
    # three instead of computing two of them. `name` is the directory under the
    # state dir and `title` is what a human sees in the reader.
    Feed = Struct.new(:name, :title, :id, :url, :addresses, keyword_init: true)

    # A feed name is a directory name. Lowercase, and no dots at the front, no
    # slashes anywhere, so "..", "/etc" and a hidden directory are all
    # unrepresentable rather than merely unlikely.
    NAME_PATTERN = /\A[a-z0-9][a-z0-9_-]*\z/

    # Deliberately not an RFC 5322 address parser. An address that needs one has
    # no business being a feed address: OpenSMTPD replaces characters it finds
    # suspicious with ":" before we ever see the recipient, so the alphabet a
    # feed address can safely use is narrow anyway. See the README.
    ADDRESS_PATTERN = /\A[^@\s<>,;"]+@[^@\s<>,;"]+\z/

    class << self
      # --config wins, then the environment, then the compiled-in path. An
      # empty environment variable counts as unset: `MAIL2RSS26_CONFIG=` in a
      # systemd unit is how one gets un-set, and reading it as a path to "" only
      # produces a confusing ENOENT.
      def path(explicit = nil)
        return explicit if explicit && !explicit.empty?

        from_env = ENV[PATH_ENV]
        from_env && !from_env.empty? ? from_env : DEFAULT_PATH
      end

      def load(path)
        # UTF-8 explicitly, not the locale's idea of an encoding. A delivery
        # runs with no environment, which makes Encoding.default_external
        # US-ASCII, and a feed titled "Wielkie Okazje – tygodnik" would then
        # fail to load *on the server only*. JSON is UTF-8 by definition
        # (RFC 8259), so there is nothing to guess.
        parse(File.read(path, encoding: Encoding::UTF_8), path)
      rescue SystemCallError => e
        # Missing, unreadable, a directory: all the same to the operator, and
        # all Config::Error rather than a bare SystemCallError. Both defer, so
        # the distinction is no longer in the exit code — it is in this message,
        # which is why the message has to name the file that must change.
        raise Error, "cannot read config #{path}: #{e.message}"
      end

      def parse(text, path = "<config>")
        document = JSON.parse(text)
        raise Error, "#{path}: the top level must be a JSON object" unless document.is_a?(Hash)

        check_version(document["version"], path)
        new(path: path,
            state_dir: optional_string(document["stateDir"], "stateDir", path),
            feeds: feeds(document["feeds"], path))
      rescue JSON::ParserError => e
        raise Error, "#{path} is not valid JSON: #{e.message}"
      end

      private

      def check_version(version, path)
        return if version == SCHEMA_VERSION

        raise Error, "#{path}: version must be #{SCHEMA_VERSION}, got #{version.inspect}"
      end

      def feeds(feeds, path)
        # An object keyed by feed name rather than a list of objects: it is the
        # shape `attrsOf submodule` serialises to, so the Phase 6 module is a
        # `builtins.toJSON` of the option and nothing else, and duplicate feed
        # names become impossible instead of validated.
        raise Error, "#{path}: \"feeds\" must be a JSON object keyed by feed name" unless feeds.is_a?(Hash)

        feeds.map { |name, feed| build(name, feed, path) }.sort_by(&:name)
      end

      def build(name, feed, path)
        unless NAME_PATTERN.match?(name)
          raise Error, "#{path}: #{name.inspect} is not a usable feed name " \
                       "(it becomes a directory: #{NAME_PATTERN.source})"
        end
        raise Error, "#{path}: feed #{name}: must be a JSON object" unless feed.is_a?(Hash)

        Feed.new(name: name,
                 title: required_string(feed["title"], "#{name}.title", path),
                 id: required_string(feed["id"], "#{name}.id", path),
                 url: optional_string(feed["url"], "#{name}.url", path),
                 addresses: addresses(feed["addresses"], name, path))
      end

      def addresses(addresses, name, path)
        unless addresses.is_a?(Array) && !addresses.empty?
          raise Error, "#{path}: feed #{name}: \"addresses\" must be a non-empty array"
        end

        addresses.map do |address|
          value = required_string(address, "#{name}.addresses[]", path)
          unless ADDRESS_PATTERN.match?(value)
            raise Error, "#{path}: feed #{name}: #{value.inspect} is not a usable address"
          end

          Config.normalise(value)
        end
      end

      def required_string(value, field, path)
        unless value.is_a?(String) && !value.strip.empty?
          raise Error, "#{path}: #{field} must be a non-empty string, got #{value.inspect}"
        end

        value.strip
      end

      def optional_string(value, field, path)
        return nil if value.nil?

        required_string(value, field, path)
      end
    end

    # The form both sides of a lookup are reduced to. Case is dropped on the
    # whole address: the domain is case-insensitive by RFC 5321 and the local
    # part is not, but a feed address is a token *we* mint, so insisting on its
    # case would only ever lose a newsletter to a mailer that upcased it. The
    # angle brackets go because some agents hand over "<a@b>" and the mail is
    # for the same feed either way.
    def self.normalise(address)
      address.to_s.strip.delete_prefix("<").delete_suffix(">").strip.downcase
    end

    # Plus-addressing, applied to the *recipient* only. "weekly.a41f9d+news@"
    # is the same feed as "weekly.a41f9d@", because a sender that invents a tag
    # (some do, to thread their own bounces) must not cost us the newsletter. A
    # configured address containing a "+" still matches exactly and first, so
    # tagging can be configured explicitly where that is the intent.
    def self.without_tag(address)
      local, at, domain = address.partition("@")
      return nil if at.empty?

      bare = local.split("+", 2).first.to_s
      bare.empty? ? nil : "#{bare}@#{domain}"
    end

    attr_reader :path, :feeds, :state_dir

    def initialize(feeds:, state_dir: nil, path: nil)
      @feeds = feeds
      @state_dir = state_dir
      @path = path
      @by_address = index(feeds)
    end

    # F5, on the delivery side: nil means no feed, means EX_NOUSER, means
    # nothing gets written. There is no catch-all and there is not going to be
    # one — a feed that is not in the configuration does not exist.
    def feed_for(recipient)
      address = Config.normalise(recipient)
      bare = Config.without_tag(address)

      @by_address[address] || (bare && @by_address[bare])
    end

    def feed_named(name)
      @feeds.find { |feed| feed.name == name }
    end

    private

    def index(feeds)
      feeds.each_with_object({}) do |feed, table|
        feed.addresses.each do |address|
          # Two feeds claiming one address is not a preference we can guess at,
          # and picking either one silently files someone's newsletter in the
          # wrong place forever.
          if table.key?(address)
            raise Error, "#{@path}: #{address} is claimed by both #{table[address].name} and #{feed.name}"
          end

          table[address] = feed
        end
      end
    end
  end
end
